import urllib.request, json, time

def get_paper(paper_id):
    fields = 'paperId,title,year,venue,authors,externalIds,url,citationCount'
    url = f'https://api.semanticscholar.org/graph/v1/paper/{paper_id}?fields={fields}'
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=15) as resp:
            return json.loads(resp.read())
    except Exception as e:
        return {'error': str(e)}

# Try known DOIs and title searches
papers_to_lookup = [
    'DOI:10.1111/1467-8721.00158',  # Ferreira Bailey Ferraro 2002
    'DOI:10.1016/j.tics.2007.01.003',  # Ferreira Patson 2007 (Trends in Cognitive Sciences)
    'DOI:10.1016/0010-0285(82)90008-1',  # Frazier Rayner 1982
    'DOI:10.1016/j.cognition.2007.05.006',  # Levy 2008
]

for pid in papers_to_lookup:
    time.sleep(0.5)
    result = get_paper(pid)
    if 'error' not in result:
        authors = [a.get('name','') for a in result.get('authors',[])]
